import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        System.out.print(calculate(n));
        scanner.close();
    }

    private static int calculate(int n) {
        int N = 2 * n;
        int[][][] dp = new int[N + 1][N + 1][2];
        dp[0][0][0] = 0;
        dp[0][0][1] = 0;
        for (int i = 1; i <= N; i++) {
            for (int j = 0; j <= i; j++) {
                for (int k = 0; k <= 1; k++) {
                    dp[i][j][k] = 0;
                    if (k == 1) {
                        if (i - j >= 2) {
                            dp[i][j][k] = MathUtility.add(dp[i][j][k], dp[i - 1][j + 1][0], 1000000007);
                        }
                        if (j > 0) {
                            dp[i][j][k] = MathUtility.add(dp[i][j][k], dp[i - 1][j - 1][0], 1000000007);
                        }
                    } else {
                        dp[i][j][k] = Math.max(getVal(dp, i, j, false, false),
                                Math.max(getVal(dp, i, j, false, true),
                                        getVal(dp, i, j, true, false)));
                    }
                }
            }
        }
        return dp[N][0][0];
    }

    private static int getVal(int[][][] dp, int i, int j, boolean selectStart, boolean selectEnd) {
        int res = 0;
        if (i - j >= 2) {
            if (selectStart) {
                res = MathUtility.add(res, dp[i - 1][j + 1][1], 1000000007);
                res = MathUtility.add(res, 1, 1000000007);
            } else {
                res = MathUtility.add(res, dp[i - 1][j + 1][0], 1000000007);
            }
        }
        if (j > 0) {
            if (selectEnd) {
                res = MathUtility.add(res, dp[i - 1][j - 1][1], 1000000007);
                res = MathUtility.add(res, 1, 1000000007);
            } else {
                res = MathUtility.add(res, dp[i - 1][j - 1][0], 1000000007);
            }
        }
        return res;
    }

    static class MathUtility {
        public static int add(int a, int b, int MOD) {
            int res = a + b;
            if (res >= MOD) {
                res -= MOD;
            }
            return res;
        }
    }
}
