#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

const int MOD = 1000000007;

int add_mod(int a, int b) {
    int res = a + b;
    if (res >= MOD) {
        res -= MOD;
    }
    return res;
}

int getVal(const vector<vector<vector<int>>> &dp, int i, int j, bool selectStart, bool selectEnd) {
    int res = 0;
    if (i - j >= 2) {
        if (selectStart) {
            res = add_mod(res, add_mod(dp[i - 1][j + 1][1], 1));
        } else {
            res = add_mod(res, dp[i - 1][j + 1][0]);
        }
    }
    if (j > 0) {
        if (selectEnd) {
            res = add_mod(res, add_mod(dp[i - 1][j - 1][1], 1));
        } else {
            res = add_mod(res, dp[i - 1][j - 1][0]);
        }
    }
    return res;
}

int calculate(int n) {
    int N = 2 * n;
    vector<vector<vector<int>>> dp(N + 1, vector<vector<int>>(N + 1, vector<int>(2, 0)));
    // Initialization already done with zeros

    for (int i = 1; i <= N; i++) {
        for (int j = 0; j <= i; j++) {
            for (int k = 0; k <= 1; k++) {
                if (k == 1) {
                    if (i - j >= 2) {
                        dp[i][j][k] = add_mod(dp[i][j][k], dp[i - 1][j + 1][0]);
                    }
                    if (j > 0) {
                        dp[i][j][k] = add_mod(dp[i][j][k], dp[i - 1][j - 1][0]);
                    }
                } else {
                    int val1 = getVal(dp, i, j, false, false);
                    int val2 = getVal(dp, i, j, false, true);
                    int val3 = getVal(dp, i, j, true, false);
                    dp[i][j][k] = max(val1, max(val2, val3));
                }
            }
        }
    }
    return dp[N][0][0];
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    cout << calculate(n);
    return 0;
}

